import json
from pathlib import Path

drafts = {}


def add(number, xml, reason, review_notes):
    assert number not in drafts
    drafts[number] = {
        'proposed_xml': xml.strip(),
        'reason': reason,
        'review_notes': review_notes,
        'status': 'rewrite_draft',
    }


add('L316-2', """
<p>Les agents de la direction générale des finances publiques peuvent communiquer aux agents des administrations compétentes, commissionnés à cet effet, tous les renseignements permettant de déterminer si les logements construits avec la participation financière de l'Etat constituent des résidences principales.</p>
<p>Les agents destinataires commissionnés à cette fin sont soumis au secret professionnel.</p>
""", "Réécriture à droit constant : la phrase précise les agents qui transmettent les renseignements, leurs destinataires et la finalité de la transmission. L'obligation de secret professionnel reste dans le second alinéa. Aucune réforme de fond n'est introduite.",
"L'habilitation reste limitée à la vérification du caractère de résidence principale des logements construits avec la participation financière de l'Etat. Le commissionnement des destinataires et le secret professionnel sont maintenus ; aucune faculté générale d'échange de données n'est créée.")

add('L316-3', """
<p>L'inspection générale des finances contrôle, sur pièces et sur place :</p>
<p>1° La société mentionnée au dernier alinéa de l'article L. 312-1, pour les missions que lui confie l'article L. 315-5-1 et pour sa participation à la distribution des avances sans intérêt instituées en application des articles L. 301-1 et L. 301-2 et des prêts mentionnés au troisième alinéa de l'article L. 312-1 ;</p>
<p>2° Les établissements de crédit et les sociétés de financement, pour leur participation aux opérations relatives au régime de l'épargne-logement mentionné à l'article L. 315-1, à la distribution des avances sans intérêt instituées en application des articles L. 301-1 et L. 301-2 ou à celle des prêts mentionnés au troisième alinéa de l'article L. 312-1.</p>
<p>Les sanctions prévues au III de l'article 43 de la loi n° 96-314 du 12 avril 1996 portant diverses dispositions d'ordre économique et financier sont applicables. En outre, si un contrôle de l'inspection générale des finances révèle que des subventions versées aux établissements de crédit ou aux sociétés de financement en application de l'article R. 317-1 ont été utilisées en méconnaissance des articles R. 317-1 et suivants, le ministre chargé de l'économie peut en ordonner le remboursement, à hauteur des sommes affectées à un autre objet que celui prévu. Ce remboursement peut également être imposé à la société mentionnée au dernier alinéa de l'article L. 312-1 pour les activités qu'elle exerce au titre du troisième alinéa du même article L. 312-1, de l'article L. 315-5-1 et de l'article R. 317-14. Pour ces mêmes activités, cette société, les établissements de crédit et les sociétés de financement sont aussi soumis à un contrôle sur pièces et sur place par des agents mandatés conjointement à cet effet par le ministre chargé de l'économie et des finances et le ministre chargé du logement, dans les conditions définies par décret.</p>
""", "Réécriture à droit constant : les activités contrôlées sont rattachées explicitement à chaque catégorie d'organismes. Le dernier alinéa distingue l'application des sanctions légales, le remboursement des subventions détournées de leur objet et le contrôle ministériel conjoint, sans modifier leurs conditions.",
"Subdivisions 1° et 2° et dernier alinéa conservés. Les renvois au dernier et au troisième alinéas de L. 312-1 correspondent aux cibles présentes dans le corpus consulté. La source vise encore R. 317-1 et suivants et R. 317-14, non retrouvés dans le corpus fourni : leur portée historique doit être contrôlée sans supprimer les contrôles ou les restitutions afférents aux opérations anciennes. Référence au III de l'article 43 de la loi du 12 avril 1996 conservée. Seule la présentation de R317-1 est harmonisée en R. 317-1.")

add('L316-4', """
<p>La Cour des comptes contrôle, sur pièces et sur place :</p>
<p>1° La société mentionnée au dernier alinéa de l'article L. 312-1, pour les missions que lui confie l'article L. 315-5-1 et pour sa participation à la distribution des avances sans intérêt instituées en application des articles L. 301-1 et L. 301-2 et des prêts mentionnés au troisième alinéa de l'article L. 312-1 ;</p>
<p>2° Les établissements de crédit et les sociétés de financement, pour leur participation aux opérations relatives au régime de l'épargne-logement mentionné à l'article L. 315-1, à la distribution des avances sans intérêt instituées en application des articles L. 301-1 et L. 301-2 ou à celle des prêts mentionnés au troisième alinéa de l'article L. 312-1.</p>
""", "Réécriture à droit constant : l'action de la Cour des comptes est exprimée directement et les trois catégories d'opérations des prêteurs sont énoncées de manière parallèle. Le champ du contrôle sur pièces et sur place n'est pas modifié.",
"Les 1° et 2°, les missions de L. 315-5-1, l'épargne-logement et les deux catégories de financements sont conservés. Les renvois au dernier et au troisième alinéas de L. 312-1 ont été vérifiés dans le corpus ; aucune substitution d'un autre contrôle à celui de la Cour des comptes.")

add('L31-10-1', """
<p>Dans les conditions fixées par le présent chapitre, les établissements de crédit et les sociétés de financement peuvent accorder des prêts sans intérêt. L'octroi de ces prêts leur ouvre droit au crédit d'impôt prévu à l'article 244 quater V du code général des impôts.</p>
""", "Réécriture à droit constant : les prêteurs autorisés, les conditions du chapitre et le crédit d'impôt qui bénéficie aux prêteurs sont présentés dans deux phrases directes. Aucun élargissement du prêt ou du crédit d'impôt n'est proposé.",
"Le renvoi à l'article 244 quater V du CGI a été vérifié dans le corpus. La note source rattache l'application aux prêts émis du 1er janvier 2011 au 31 décembre 2023, en citant l'article 90, V, de la loi n° 2010-1657 et l'article 87, I, de la loi n° 2021-1900. Cette échéance historique coexiste avec des articles du chapitre applicables aux offres émises à compter du 1er avril 2024 ; la coordination temporelle doit être contrôlée. Aucune nouvelle échéance n'est inventée ni cette note transformée en date de réforme.")

add('L31-10-2', """
<p>Les personnes physiques peuvent obtenir les prêts prévus au présent chapitre, sous condition de ressources, pour acquérir ou faire construire leur résidence principale en accession à la première propriété, ou pour acquérir en première propriété les droits réels immobiliers de leur résidence principale dans le cadre d'un bail réel solidaire.</p>
<p>Pour un logement neuf, l'octroi du prêt est subordonné à deux conditions : le logement doit se situer dans un bâtiment d'habitation collectif au sens du 6° de l'article L. 111-1 et dans une commune classée dans une zone géographique où un déséquilibre important entre l'offre et la demande de logements entraîne des difficultés d'accès au logement dans le parc résidentiel existant. Ces deux conditions ne s'appliquent toutefois pas à l'aménagement, avec ou sans acquisition, de locaux non destinés à l'habitation en locaux à usage de logement. Elles ne s'appliquent pas non plus à l'acquisition d'un logement neuf faisant l'objet d'un contrat régi par la loi n° 84-595 du 12 juillet 1984 définissant la location-accession à la propriété immobilière, d'un contrat de bail réel solidaire régi par le chapitre V du titre V du livre II du présent code ou d'un contrat d'accession à la propriété respectant les conditions prévues au 2° du III de l'article 278 sexies du code général des impôts.</p>
<p>Pour un logement ancien, le prêt est accordé soit sous condition de vente du parc social à ses occupants, soit sous condition de travaux et de localisation du logement dans une commune classée dans une zone géographique où l'offre et la demande de logements ne présentent pas de déséquilibre important entraînant des difficultés d'accès au logement dans le parc résidentiel existant.</p>
<p>Les ministres chargés du budget et du logement classent les communes par zone géographique, par arrêté, en tenant compte principalement des besoins en logements ainsi que des prix de vente et des loyers de l'immobilier résidentiel.</p>
<p>Un arrêté des ministres chargés du budget et du logement précise, parmi les zones géographiques définies au quatrième alinéa, celles qui satisfont aux conditions de localisation prévues aux deuxième et troisième alinéas.</p>
<p>Ces prêts ne peuvent donner lieu à la perception de frais de dossier ou d'expertise, ni d'intérêts ou d'intérêts intercalaires.</p>
<p>Pour l'acquisition d'un logement faisant l'objet d'un contrat régi par la loi n° 84-595 du 12 juillet 1984 définissant la location-accession à la propriété immobilière, l'emprunteur peut opter, lors de l'offre de prêt et dans les conditions fixées par décret, pour l'application des dispositions du présent chapitre en vigueur à la date de signature de ce contrat.</p>
<p>Une même opération ne peut donner lieu qu'à un seul prêt sans intérêt prévu au présent chapitre. Lorsqu'elle est financée par ce prêt, elle ne peut pas bénéficier de l'avance mentionnée à l'article 244 quater J du code général des impôts.</p>
""", "Réécriture à droit constant : les conditions du neuf et de l'ancien, leurs dérogations, le classement territorial, l'absence de frais et les règles de cumul sont rendus explicites. Les huit alinéas normatifs sont matérialisés séparément, sans déplacer l'option de location-accession du septième alinéa. Aucune réforme des critères du prêt n'est introduite.",
"Conserver les cibles des deuxième à septième alinéas : D. 31-10-2-1 vise expressément le septième pour l'option de location-accession ; L. 31-10-3, V, vise le troisième. Les dérogations du neuf portent sur les deux conditions du deuxième alinéa ; la vente du parc social reste une branche distincte des conditions cumulées de travaux et de localisation. La note source vise les offres émises à compter du 1er avril 2024 (décret n° 2024-304, article 12). La fiche source annonce une abrogation différée au 1er janvier 2027 : la version applicable devra être coordonnée sans antidater une réforme. L'aide à la transformation de locaux ne crée ici aucune dérogation générale aux règles de sécurité, d'accessibilité ou de salubrité.")

add('L31-10-3', """
<p>I. - La condition de première propriété prévue à l'article L. 31-10-2 est remplie par les personnes physiques qui, au cours des deux années précédant l'émission de l'offre de prêt, n'ont pas été propriétaires de leur résidence principale ou n'ont pas acquis les droits réels immobiliers de celle-ci dans le cadre d'un bail réel solidaire.</p>
<p>Cette condition n'est toutefois pas exigée si le bénéficiaire du prêt ou l'une des personnes occupant le logement à titre principal :</p>
<p>a) Détient la carte « mobilité inclusion » portant la mention « invalidité » prévue au 1° du I de l'article L. 241-3 du code de l'action sociale et des familles, ou une carte d'invalidité délivrée sur le fondement du même article L. 241-3 dans sa rédaction antérieure au 1er janvier 2017 ;</p>
<p>a bis) Perçoit une pension d'invalidité correspondant à un classement dans l'une des catégories prévues aux 2° et 3° de l'article L. 341-4 du code de la sécurité sociale ;</p>
<p>b) Est bénéficiaire d'une allocation attribuée en application des articles L. 541-1 à L. 541-3 ou L. 821-1 à L. 821-8 du même code ;</p>
<p>c) A subi une catastrophe qui a rendu sa résidence principale définitivement inhabitable.</p>
<p>II. - La condition de ressources prévue à l'article L. 31-10-2 est remplie lorsque le montant total des ressources des personnes physiques, mentionné au c de l'article L. 31-10-4 et divisé par le coefficient familial apprécié selon les modalités de l'article L. 31-10-12, est inférieur à un plafond fixé par décret selon la localisation du logement. Ce plafond est compris entre 16 500 € et 49 000 €. Un décret précise comment déterminer les ressources à retenir et la période de référence pour apprécier cette condition.</p>
<p>III. - Abrogé.</p>
<p>IV. - La condition de vente du parc social à ses occupants prévue à l'article L. 31-10-2 est remplie pour les opérations portant sur un logement d'un organisme d'habitation à loyer modéré mentionné à l'article L. 411-2 ou sur un logement d'une société d'économie mixte mentionnée à l'article L. 481-1 faisant l'objet d'une convention conclue en application de l'article L. 351-2, lorsque ce logement est acquis par les personnes mentionnées au premier alinéa du II ou au deuxième alinéa du III de l'article L. 443-11.</p>
<p>V. - La condition de travaux prévue au troisième alinéa de l'article L. 31-10-2 est remplie pour les logements anciens qui font l'objet, au moment de l'acquisition, d'un programme de travaux d'amélioration. Ce programme est présenté soit par l'acquéreur, soit par le vendeur dans le cadre d'une vente d'immeuble à rénover mentionnée à l'article L. 262-1 ou pour un logement ayant donné lieu à un contrat régi par la loi n° 84-595 du 12 juillet 1984 définissant la location-accession à la propriété immobilière, lorsque ce logement fait l'objet, dans les conditions fixées par décret, d'une convention et d'une décision d'agrément du représentant de l'Etat dans le département. Les travaux d'amélioration doivent être réalisés dans un délai qui ne peut dépasser trois ans à compter de l'émission de l'offre de prêt, sous réserve des exceptions, dans les conditions fixées par décret, tenant au décès de l'emprunteur, à un accident de santé de celui-ci entraînant une interruption temporaire de travail d'au moins trois mois, à un état de catastrophe naturelle ou technologique, à une contestation contentieuse de l'opération ou à la force majeure. Ces travaux doivent permettre d'atteindre un niveau de performance énergétique défini par arrêté conjoint des ministres chargés du logement, de l'économie et du budget. Leur montant doit être supérieur à une quotité du coût total de l'opération mentionné au a de l'article L. 31-10-4. Cette quotité est fixée par décret entre 20 % et 30 % du coût total de l'opération.</p>
""", "Réécriture à droit constant : chaque condition est formulée directement, les exceptions de première propriété gardent leurs lettres et le V est décomposé en phrases sur le programme, les opérations du vendeur, le délai et les caractéristiques des travaux. Le délai de trois ans du prêt n'est pas remplacé par la voie locative de vingt-quatre mois du projet, qui relève d'un autre régime. Aucune réforme de fond n'est introduite.",
"I à V, a, a bis, b et c conservés, avec III abrogé. Maintien des deux ans, du 1er janvier 2017, des plafonds de 16 500 € et 49 000 €, des trois ans, de l'interruption d'au moins trois mois et de la fourchette de 20 % à 30 % ; le montant des travaux reste strictement supérieur à la quotité. Toutes les exceptions au délai sont maintenues. Le V source comporte une syntaxe défectueuse et la coquille « améliorationpermettant » : l'articulation du programme présenté par le vendeur avec la vente à rénover ou la location-accession agréée est éclairée par D. 31-10-2, I, consulté dans le corpus, sans supprimer aucune branche. Le IV conserve le renvoi source à L. 351-2 : la note source signale sa substitution par L. 353-1, L. 821-2, L. 831-1 et L. 831-2 (ordonnance n° 2019-770, article 2) ; la cible pertinente de conventionnement, notamment L. 831-1, reste à coordonner expressément. Le renvoi à L. 443-11 a été vérifié. La note relative aux tables du code général de la fonction publique est sans rapport avec cet article. Applicabilité historique aux offres émises à compter du 1er avril 2024 conservée dans la note de contrôle.")

add('L31-10-4', """
<p>Les caractéristiques du prêt sont déterminées en fonction :</p>
<p>a) Du coût total de l'opération, toutes taxes comprises ;</p>
<p>b) Du nombre de personnes qui occuperont le logement à titre de résidence principale ;</p>
<p>c) De l'ensemble des ressources des personnes mentionnées au b ;</p>
<p>d) De la zone géographique où se situe le logement, définie dans les conditions fixées par décret en fonction du déséquilibre entre l'offre et la demande de logements ;</p>
<p>e) Du caractère neuf du logement ou, s'il est ancien, du respect de la condition de travaux prévue au V de l'article L. 31-10-3.</p>
""", "Réécriture à droit constant : l'énumération rattache directement les caractéristiques du prêt à chacun des cinq critères, avec une formulation plus simple du nombre d'occupants et de la localisation. Aucune modification des critères financiers ou territoriaux n'est proposée.",
"Lettres a à e et ordre des critères maintenus, notamment a pour le coût total et c pour les ressources, visés par les articles suivants. Le coût reste toutes taxes comprises et les ressources comprennent celles de tous les futurs occupants à titre principal. La note source vise les offres émises à compter du 1er janvier 2016 (article 107, III, A, de la loi n° 2015-1785).")

add('L31-10-6', """
<p>Pendant les six années qui suivent la date de versement du prêt, l'emprunteur doit conserver le logement comme résidence principale et ne peut le proposer à la location, sauf dans les cas d'exception définis par décret.</p>
<p>En cas de mutation du logement, l'emprunteur peut continuer à bénéficier du prêt en transférant le capital restant dû pour acquérir ou construire une nouvelle résidence principale.</p>
""", "Réécriture à droit constant : les obligations d'occupation et l'interdiction de proposer le logement à la location ont pour sujet explicite l'emprunteur. Le maintien du prêt par transfert est exprimé directement, sans changer ses conditions ni les exceptions réglementaires.",
"Deux alinéas conservés. Le délai reste de six ans à compter du versement, et non de l'offre. La mutation, le transfert du capital restant dû et la nouvelle résidence principale sont maintenus. Selon la note source, application aux offres émises à compter du 1er janvier 2016 et, avec l'accord de l'emprunteur et du prêteur, aux prêts versés depuis le 1er janvier 2011. Ces accords ne sont pas supprimés par la réécriture. La voie de rénovation locative de vingt-quatre mois ne constitue pas une nouvelle exception à l'occupation du logement financé par ce prêt.")

add('L31-10-7', """
<p>L'établissement de crédit ou la société de financement peut prévoir dans son offre de prêt sans intérêt :</p>
<p>a) Un ajustement du montant ou des conditions du prêt, dans les conditions fixées par décret, lorsque les conditions prévues au présent chapitre n'ont pas été respectées et que ce manquement est imputable à l'emprunteur. Cet ajustement doit rendre l'avantage procuré par le prêt équivalent à celui du prêt qui aurait dû lui être accordé ;</p>
<p>b) L'exigibilité du remboursement du capital restant dû lorsque les conditions de maintien du prêt prévues à l'article L. 31-10-6 ne sont plus respectées.</p>
<p>Le prêteur doit préciser dans le contrat de prêt les obligations d'information de l'emprunteur, notamment en cas de changement de situation.</p>
""", "Réécriture à droit constant : les deux clauses que le prêteur peut prévoir sont séparées et l'ajustement est expliqué par son fait déclencheur puis par son résultat. L'obligation contractuelle d'information reste distincte. Aucune exigibilité automatique nouvelle n'est créée.",
"Lettres a et b et dernier alinéa conservés. L'imputabilité à l'emprunteur reste requise au a ; l'équivalence porte sur l'avantage du prêt qui aurait dû être octroyé. Le b conserve son renvoi à L. 31-10-6. La note source vise les prêts émis du 1er janvier 2011 au 31 décembre 2017 en citant l'article 90, V, de la loi n° 2010-1657 et l'article 59 de la loi n° 2014-1654 ; cette échéance ancienne nécessite une coordination avec les prolongations du dispositif, sans qu'une nouvelle date soit inventée ici.")

add('L31-10-8', """
<p>Le montant du prêt est calculé en appliquant une quotité au coût total de l'opération, retenu dans la limite d'un plafond. Ce montant ne peut dépasser celui du ou des autres prêts qui financent la même opération et dont la durée est au moins égale à deux ans. Toutefois, lorsque la quotité prévue à la première phrase est de 50 %, le montant du prêt peut dépasser celui de ces autres prêts ; l'excédent est limité au quart du montant de ces autres prêts.</p>
<p>Si la durée totale des périodes de remboursement du prêt est inférieure ou égale à huit ans, l'emprunteur peut demander une réduction du montant du prêt, limitée à la moitié de ce montant.</p>
""", "Réécriture à droit constant : le calcul du prêt, le plafond lié aux autres financements et la dérogation à 50 % sont formulés en étapes lisibles. La faculté de réduction à la demande de l'emprunteur conserve ses seuils et sa limite.",
"Deux alinéas conservés. Maintien de la durée minimale de deux ans des autres prêts, du taux de 50 %, de l'excédent maximal d'un quart et du seuil inclusif de huit ans. La réduction peut atteindre la moitié du prêt, sans être nécessairement de moitié. La note source rattache ces dispositions aux offres émises à compter du 1er avril 2024 (décret n° 2024-304, article 12).")

add('L31-10-9', """
<p>Un décret fixe la quotité prévue à l'article L. 31-10-8 en tenant compte des ressources de l'emprunteur, de la localisation du logement et de son caractère neuf ou, pour un logement ancien, du respect de la condition de travaux prévue au V de l'article L. 31-10-3. Cette quotité est comprise entre 10 % et 50 %.</p>
<p>Pour les logements neufs dont la performance énergétique globale dépasse un ou plusieurs niveaux fixés par décret, la quotité prévue au premier alinéa est toutefois majorée, sans pouvoir dépasser 50 %.</p>
""", "Réécriture à droit constant : l'auteur de la fixation de la quotité est explicite et les bornes sont exprimées sous forme d'intervalle. La majoration énergétique est maintenue dans son alinéa, avec le même plafond. Aucune hausse ou baisse du financement n'est proposée.",
"Bornes inclusives de 10 % et 50 % et plafond de 50 % de la majoration conservés. Le critère énergétique reste propre aux logements neufs et peut se référer à un ou plusieurs niveaux réglementaires. Les renvois à L. 31-10-8 et au V de L. 31-10-3 sont maintenus. Note source : offres émises à compter du 1er avril 2024, conformément à l'article 12 du décret n° 2024-304.")

add('L31-10-10', """
<p>Le coût total de l'opération inclut le coût des travaux que l'emprunteur prévoit, le cas échéant, lors de l'acquisition. Sont toutefois exclus les montants financés par les avances mentionnées aux articles 244 quater T et 244 quater U du code général des impôts ainsi que, pour un logement ancien, le coût des travaux d'installation d'un dispositif de chauffage fonctionnant aux énergies fossiles.</p>
<p>Le plafond du coût total de l'opération retenu pour le calcul du prêt est égal au montant maximal d'opération pour une personne seule, multiplié par un coefficient familial, le résultat étant arrondi au millier d'euros le plus proche.</p>
<p>Un décret fixe le montant maximal d'opération pour une personne seule selon la localisation du logement. Ce montant est compris entre 79 000 € et 156 000 €.</p>
<p>Le coefficient familial prévu au deuxième alinéa dépend du nombre de personnes qui occuperont le logement à titre de résidence principale, selon le tableau suivant :</p>
<table><tbody><tr><td>Nombre de personnes</td><td>1</td><td>2</td><td>3</td><td>4</td><td>5 et plus</td></tr><tr><td>Coefficient familial</td><td>1,0</td><td>1,5</td><td>1,8</td><td>2,1</td><td>2,4</td></tr></tbody></table>
""", "Réécriture à droit constant : les travaux inclus et les exclusions sont distingués ; le calcul du plafond et l'arrondi sont explicités. Le tableau est reproduit intégralement, avec toutes ses valeurs, en retirant seulement les attributs de présentation interdits. Aucune modification des montants ou coefficients n'est introduite.",
"Quatre alinéas suivis du tableau conservés ; le deuxième reste la cible du renvoi sur le coefficient. Contrôle des bornes de 79 000 € et 156 000 €, de l'arrondi au millier le plus proche et des cinq coefficients : 1,0 ; 1,5 ; 1,8 ; 2,1 ; 2,4 pour respectivement 1, 2, 3, 4, 5 personnes et plus. Les deux avances du CGI restent exclues ; l'exclusion du chauffage fossile reste limitée au logement ancien. La note source vise les offres émises à compter du 1er avril 2024 (décret n° 2024-304, article 12).")

add('L31-10-11', """
<p>Les conditions de remboursement du prêt sont fixées à la date d'émission de l'offre.</p>
<p>Selon les ressources de l'emprunteur et les modalités prévues à l'article L. 31-10-12, le prêt est remboursé en une seule période ou, si le remboursement d'une fraction ou de la totalité de son montant est différé, en deux périodes. Chaque période comporte des mensualités constantes. Si le différé porte sur la totalité du prêt, les mensualités de la première période définie au même article L. 31-10-12 sont toutefois nulles.</p>
<p>En cas de différé de remboursement, la première période prévue au même article L. 31-10-12 ne peut durer plus longtemps que le plus long des autres prêts finançant l'opération.</p>
<p>L'emprunteur peut demander que la première période de remboursement soit raccourcie. Sa durée ne peut toutefois être inférieure à deux ans.</p>
<p>Une période de mise à disposition des fonds peut précéder la première période de remboursement. L'emprunteur n'effectue aucun remboursement pendant cette période de mise à disposition.</p>
""", "Réécriture à droit constant : les phrases séparent le nombre de périodes, la constance des mensualités, le différé total et les limites de durée. La période de mise à disposition des fonds conserve son alinéa final et son absence de remboursement. Aucune réforme de la durée du prêt n'est introduite.",
"Cinq alinéas maintenus, notamment le dernier visé par l'article 244 quater V, II, du CGI vérifié dans le corpus. La date de l'offre reste déterminante. Maintien des différés partiel et total, des mensualités constantes, des mensualités nulles en différé total, du plafond lié au plus long autre prêt et du minimum de deux ans sur demande de réduction. Note source : offres émises à compter du 1er avril 2024 (décret n° 2024-304, article 12).")

add('L31-10-12', """
<p>Un décret fixe, selon un maximum de dix tranches, la fraction du prêt dont le remboursement est différé et la durée de chacune des périodes de remboursement. Il tient compte de la localisation du logement et du montant total des ressources mentionné au c de l'article L. 31-10-4, divisé par le coefficient familial prévu à l'article L. 31-10-10. Pour ce calcul, ce coefficient est majoré de 0,3 pour chaque personne qui occupera le logement à titre de résidence principale au-delà de la cinquième, sans prendre en compte plus de huit personnes au total.</p>
<p>La durée totale de remboursement du prêt est limitée à vingt-cinq ans.</p>
""", "Réécriture à droit constant : la phrase de calcul est décomposée pour distinguer les tranches, les ressources divisées par le coefficient et la majoration de ce coefficient. Le plafond de durée demeure dans le second alinéa. Aucun paramètre financier n'est modifié.",
"Deux alinéas maintenus. Maximum de dix tranches, majoration de 0,3 par personne au-delà de la cinquième, limite de huit personnes et durée totale de vingt-cinq ans conservés. La majoration porte sur le coefficient familial, non sur les ressources ni sur la quotité du prêt. Les renvois au c de L. 31-10-4 et à L. 31-10-10 sont conservés. La note source vise les offres émises à compter du 1er janvier 2015 (article 59, IV, de la loi n° 2014-1654).")

add('L31-10-13', """
<p>Pour être habilité à accorder les prêts prévus au présent chapitre, l'établissement de crédit ou la société de financement doit conclure une convention avec l'Etat. Cette convention doit être conforme à une convention-type approuvée par arrêté conjoint des ministres chargés de l'économie et du logement.</p>
""", "Réécriture à droit constant : l'habilitation est exprimée comme une condition imposée au prêteur, puis la conformité de la convention au modèle ministériel est énoncée séparément. Aucune modification de l'autorité compétente ou de la procédure n'est introduite.",
"Convention avec l'Etat et arrêté conjoint des deux ministres conservés. La note source vise les prêts émis du 1er janvier 2011 au 31 décembre 2023, en citant l'article 90, V, de la loi n° 2010-1657 et l'article 87, I, de la loi n° 2021-1900 : contrôler la coordination de cette échéance avec les versions ultérieures du dispositif. Aucune nouvelle date d'application n'est créée.")

add('L31-10-14', """
<p>Les ministres chargés de l'économie et du logement peuvent confier à la société de gestion mentionnée au dernier alinéa de l'article L. 312-1 la gestion, le suivi et le contrôle des crédits d'impôt dus au titre des prêts prévus au présent chapitre.</p>
<p>Le contrôle exercé par cette société ne porte pas atteinte à celui de l'administration fiscale. Celle-ci reste seule compétente pour procéder aux rectifications.</p>
<p>L'établissement de crédit ou la société de financement conclut avec la société de gestion une convention conforme à une convention-type approuvée par arrêté conjoint des ministres chargés de l'économie et du logement. Cette convention précise les modalités de déclaration des prêts par le prêteur, de contrôle de leur éligibilité et de suivi des crédits d'impôt prévus à l'article 244 quater V du code général des impôts.</p>
<p>La convention doit obliger l'établissement de crédit ou la société de financement à indiquer à l'emprunteur, dans l'offre et dans le contrat de prêt sans intérêt, le montant du crédit d'impôt correspondant prévu au même article 244 quater V.</p>
""", "Réécriture à droit constant : les ministres, la société de gestion, le prêteur et l'administration fiscale sont chacun sujets de leurs compétences ou obligations. Les deux supports d'information de l'emprunteur sont explicités. Aucun transfert du pouvoir fiscal de rectification n'est proposé.",
"Quatre alinéas conservés. Gestion, suivi et contrôle des crédits d'impôt, exclusivité des rectifications fiscales, convention-type et information dans l'offre comme dans le contrat maintenus. Renvois au dernier alinéa de L. 312-1 et à l'article 244 quater V du CGI vérifiés dans le corpus. La note source vise les prêts émis du 1er janvier 2011 au 31 décembre 2023, sur le fondement de l'article 90, V, de la loi n° 2010-1657 modifié par l'article 87, I, de la loi n° 2021-1900 ; contrôler la coordination temporelle avec les offres régies par les versions ultérieures, sans nouvelle échéance inventée.")

add('L321-1', """
<p>I. - Dans le respect des objectifs de l'article L. 301-1, l'Agence nationale de l'habitat a pour mission de favoriser le développement et la qualité du parc existant de logements privés, en particulier leurs performances thermiques et leur adaptation à la perte d'autonomie. Elle participe à la lutte contre l'habitat indigne et dégradé, à la prévention et au traitement des copropriétés fragiles ou en difficulté, à la lutte contre la précarité énergétique et à l'amélioration des structures d'hébergement. A cette fin, elle encourage et facilite les travaux de réparation, d'assainissement, d'amélioration et d'adaptation des immeubles d'habitation, notamment de ceux qui font l'objet d'un bail rural ou commercial, ainsi que la transformation en logements de locaux non affectés à l'habitation, dès lors que ces logements sont utilisés à titre de résidence principale. Elle encourage et facilite également les opérations de résorption d'habitat insalubre et de requalification d'immeubles d'habitat privé dégradé, les opérations de résorption d'une copropriété dont l'état de carence a été déclaré conformément à l'article L. 615-6 et les opérations de portage ciblé de lots d'habitation d'une copropriété en difficulté. Elle peut conduire des actions d'assistance, d'étude ou de communication pour améliorer la connaissance du parc privé existant et de ses conditions d'occupation et pour faciliter l'accès des personnes défavorisées et des ménages à revenus modestes ou intermédiaires aux logements locatifs privés. Pour exercer ses missions, elle dispose d'un accès aux données détenues par les organismes chargés de la liquidation et du paiement de l'aide personnelle au logement, dans les conditions précisées par décret. Elle peut aussi participer au financement des travaux d'auto-réhabilitation accompagnée par des organismes agréés au titre de l'article L. 365-1. Elle peut enfin contrôler la qualité des prestations liées à la rénovation ou à l'efficacité énergétique réalisées par des entreprises détenant une certification, une qualification, un label ou un signe de qualité requis par la réglementation.</p>
<p>L'Agence nationale de l'habitat est administrée par un conseil d'administration dont les membres sont répartis en trois catégories d'effectif égal :</p>
<p>1° Des représentants de l'Etat et de ses établissements publics ;</p>
<p>2° Un député et un sénateur ainsi que des représentants de l'Assemblée des départements de France, de l'Assemblée des communautés de France, de France urbaine et de l'Association des maires de France ;</p>
<p>3° Des personnalités qualifiées, dont un représentant des propriétaires, un représentant des locataires et un représentant des professionnels de l'immobilier.</p>
<p>Les ministres chargés du logement et des finances nomment, par arrêté conjoint, le président et les membres du conseil d'administration. Le président est choisi parmi les membres mentionnés aux 2° ou 3°.</p>
<p>II. - L'Agence nationale de l'habitat peut conclure avec tout bailleur une convention conforme à l'article L. 321-4 ou à l'article L. 321-8. Le bailleur s'y engage à respecter des conditions relatives aux plafonds de ressources des locataires, aux plafonds de loyers et, le cas échéant, aux modalités de choix des locataires.</p>
<p>Un décret précise les modalités d'application du présent II et définit une procédure simplifiée d'entrée en vigueur des conventions.</p>
<p>III. - Pour accomplir sa mission, l'Agence nationale de l'habitat dispose des ressources suivantes :</p>
<p>1° Les contributions et subventions de l'Etat et de ses établissements publics, de l'Union européenne, des collectivités territoriales, de leurs groupements et de leurs établissements publics, ainsi que de toute autre personne morale publique ou privée ;</p>
<p>2° Les recettes fiscales que la loi lui affecte ;</p>
<p>3° Le produit des amendes prévues à l'article L. 651-2 ;</p>
<p>4° Les emprunts et le produit des placements financiers qu'elle est autorisée à effectuer ;</p>
<p>5° Les remboursements des aides qu'elle a accordées et qui sont annulées ;</p>
<p>6° Le produit des dons et legs ;</p>
<p>7° Les sommes correspondant aux aides accordées par les collectivités territoriales et les établissements publics de coopération intercommunale mentionnées aux articles L. 312-2-1 et L. 321-1-1, versées à l'agence en application des conventions prévues à ces articles ;</p>
<p>8° Les sommes allouées par des personnes morales publiques ou privées pour que l'agence attribue, pour leur compte, des aides à l'habitat non régies par le présent code, à condition que les logements aidés soient occupés à titre de résidence principale ;</p>
<p>9° Les ressources issues de la participation des employeurs à l'effort de construction ;</p>
<p>10° Les recettes accessoires, notamment la rémunération des services rendus aux tiers, dans les conditions fixées par le conseil d'administration.</p>
<p>III bis. - Le représentant de l'Etat dans la région, dans le département ou en Corse est le délégué de l'Agence nationale de l'habitat dans le territoire correspondant.</p>
<p>IV. - Un décret en Conseil d'Etat précise les conditions d'application du présent article. Il fixe les modalités de gestion et de fonctionnement de l'Agence nationale de l'habitat, notamment les règles particulières de majorité nécessaires à la gestion des crédits relatifs à la lutte contre l'habitat indigne et à l'amélioration des structures d'hébergement, ainsi que les utilisations de ses ressources.</p>
""", "Réécriture à droit constant : le long alinéa de missions est décomposé en phrases pour distinguer travaux, opérations sur les copropriétés, actions d'assistance, accès aux données et contrôle de qualité. La composition du conseil, les conventions et les dix ressources sont présentées avec des sujets explicites. Aucune nouvelle aide, dérogation locative ou dotation budgétaire n'est créée.",
"I, II, III, III bis et IV, trois catégories du conseil et dix ressources conservés dans leurs alinéas. Maintien des baux ruraux ou commerciaux, de la résidence principale, de la carence de L. 615-6, du portage ciblé, des revenus intermédiaires, des données d'aide personnelle au logement, de l'auto-réhabilitation agréée et de toutes les qualifications des entreprises contrôlées. La double virgule du IV source est supprimée comme coquille. Les appellations des associations du conseil restent celles de la source. La transformation des locaux non résidentiels figure déjà dans les missions : la réforme du dossier coordonné relève de L. 423-1 du code de l'urbanisme ; les solutions d'effet équivalent relèvent notamment de L. 112-4 à L. 112-9 du présent code, vérifiés dans le corpus, et doivent préserver sécurité, accessibilité et salubrité. La voie de rénovation locative de vingt-quatre mois exige hors de ce lot une modification des articles 6 et 20-1 de la loi n° 89-462 du 6 juillet 1989 et des dispositions réglementaires de décence, notamment le décret n° 2002-120 du 30 janvier 2002 : définir son champ, sa transition, les travaux contrôlés, les conséquences de leur inexécution et la compensation des surcoûts énergétiques, avec financement identifié. Le présent article ne réalise pas seul cette réforme et ne préjuge pas d'une aide automatique de l'agence.")

add('L321-1-1', """
<p>L'établissement public de coopération intercommunale ou le département qui a conclu avec l'Etat une convention en application des articles L. 301-5-1 ou L. 301-5-2 doit également conclure une convention avec l'Agence nationale de l'habitat. Cette dernière convention fixe les conditions de gestion des aides destinées aux propriétaires privés, soit par l'agence, soit, à leur demande, par l'établissement public de coopération intercommunale ou le département. Elle peut confier à l'agence, au nom et pour le compte de l'établissement public ou du département, la gestion des aides à l'habitat privé financées sur leur budget propre. Elle peut également fixer des règles particulières d'octroi des aides aux propriétaires bailleurs et occupants selon des critères économiques, sociaux ou géographiques, dans les limites prévues par décret en Conseil d'Etat.</p>
<p>La convention précise les conditions dans lesquelles le président du conseil départemental ou de l'établissement public de coopération intercommunale signe, au nom de l'agence, les conventions mentionnées à l'article L. 321-4.</p>
""", "Réécriture à droit constant : la convention obligatoire avec l'agence est distinguée de la convention avec l'Etat ; les choix de gestion et les facultés d'adaptation des aides sont énoncés dans des phrases distinctes. Les limites réglementaires et la signature au nom de l'agence sont conservées, sans réforme de fond.",
"Deux alinéas conservés. Gestion locale uniquement à la demande de l'établissement ou du département ; gestion des aides sur budget propre par l'agence au nom et pour le compte du financeur. Les propriétaires bailleurs et occupants, les trois catégories de critères et le décret en Conseil d'Etat sont maintenus. La convention locale ne peut supprimer les obligations de logement social ni créer à elle seule la dérogation locative de vingt-quatre mois envisagée par le projet.")

add('L321-1-2', """
<p>Dans le cadre du programme national de requalification des quartiers anciens dégradés prévu à l'article 25 de la loi n° 2009-323 du 25 mars 2009 de mobilisation pour le logement et la lutte contre l'exclusion, l'Agence nationale de l'habitat contribue aux actions de réhabilitation du parc privé, d'amélioration de la performance énergétique des bâtiments et de lutte contre l'habitat indigne.</p>
""", "Réécriture à droit constant : le programme de rattachement est placé en tête de phrase et les trois actions auxquelles l'agence contribue sont exprimées de manière parallèle. Aucune nouvelle mission ou ressource n'est ajoutée.",
"Les trois domaines d'action et le renvoi à l'article 25 de la loi n° 2009-323 du 25 mars 2009 sont conservés. Cette date désigne le texte historique du programme ; elle n'est pas utilisée comme date de la réforme projetée.")

add('L321-1-3', """
<p>L'Agence nationale de l'habitat, les collectivités territoriales et leurs établissements publics peuvent créer par convention des fonds locaux de réhabilitation de l'habitat privé, le cas échéant avec tout autre organisme public ou privé. Ces fonds regroupent leurs financements pour conduire des opérations de réhabilitation de l'habitat privé.</p>
<p>La convention désigne la collectivité territoriale ou l'établissement public de coopération intercommunale compétent en matière de programme local de l'habitat qui assure la gestion comptable et financière du fonds. La personne ainsi désignée instruit et traite les demandes et décide de l'attribution des aides.</p>
<p>La collectivité territoriale ou l'établissement public de coopération intercommunale désigné peut confier, contre rémunération, l'instruction et le traitement des demandes d'aides à un organisme public ou privé.</p>
<p>Un décret en Conseil d'Etat fixe les modalités de création, de gestion et d'utilisation de ces fonds locaux ainsi que les conditions du contrôle de leur gestion exercé par l'Etat ou en son nom.</p>
""", "Réécriture à droit constant : la création conventionnelle du fonds, la personne responsable, la délégation rémunérée et le contrôle sont présentés dans leurs quatre alinéas respectifs. La distinction entre décider des aides et déléguer leur instruction est rendue plus lisible. Aucun financement nouveau n'est présumé.",
"Quatre alinéas conservés. La compétence en matière de programme local de l'habitat, la gestion comptable et financière, l'instruction, le traitement et la décision d'attribution demeurent rattachés à la personne désignée. La délégation rémunérée ne porte que sur l'instruction et le traitement, pas sur la décision d'attribution. Le contrôle reste exercé par l'Etat ou en son nom, selon décret en Conseil d'Etat.")

add('L321-1-4', """
<p>En complément des missions prévues à l'article L. 321-1, l'Agence nationale de l'habitat peut contribuer au service public de la performance énergétique de l'habitat prévu à l'article L. 232-1 du code de l'énergie.</p>
""", "Réécriture à droit constant : la contribution facultative de l'agence est exprimée directement et son caractère complémentaire est placé en tête de phrase. Aucune mission obligatoire ou aide nouvelle n'est instituée.",
"Les renvois à L. 321-1 du présent code et à L. 232-1 du code de l'énergie sont conservés. Cette faculté ne vaut ni modification des règles de décence énergétique ni financement automatique de la voie de rénovation locative de vingt-quatre mois envisagée par le projet.")

add('L321-1-5', """
<p>I. - Lorsque les contrôles qu'elle effectue dans le cadre des missions définies à l'article L. 321-1 révèlent des non-conformités à la réglementation, l'Agence nationale de l'habitat peut suspendre le label ou le signe de qualité délivré à une entreprise pour une durée maximale de six mois, renouvelable une fois. Cette faculté concerne les labels ou signes de qualité auxquels est subordonné l'octroi d'aides financières pour des travaux d'installation ou de pose d'équipements, pour des travaux sur des logements destinés à réaliser des économies d'énergie ou à produire de l'énergie renouvelable, ou pour la réalisation d'un audit énergétique.</p>
<p>II. - L'Agence nationale de l'habitat informe sans délai de toute procédure de suspension l'organisme qui a délivré le label ou le signe de qualité à l'entreprise et l'autorité administrative chargée de la concurrence et de la consommation. Elle signale les non-conformités constatées dans les conditions prévues à l'article L. 221-13 du code de l'énergie.</p>
<p>III. - Un décret précise les modalités d'application du présent article. Il détermine notamment les conditions dans lesquelles le ménage conserve l'aide financière qui lui a été accordée lorsque l'agence décide, sur le fondement du I, de suspendre le label ou le signe de qualité de l'entreprise qui a réalisé les travaux.</p>
""", "Réécriture à droit constant : le fait déclencheur, la durée de suspension et les catégories de prestations sont répartis en phrases distinctes. L'information des deux destinataires et le maintien de l'aide au ménage restent soumis aux mêmes règles. Aucun pouvoir de sanction supplémentaire n'est créé.",
"I, II et III conservés. Durée maximale de six mois renouvelable une seule fois ; labels et signes de qualité, audits et deux catégories de travaux maintenus. Information sans délai de l'organisme de qualification et de l'autorité de concurrence et consommation, signalement au titre de L. 221-13 du code de l'énergie et renvoi au décret conservés. Le maintien de l'aide du ménage reste conditionné par le décret, sans garantie générale nouvelle.")

add('L321-2', """
<p>I. - Pour exercer une activité de mandataire des bénéficiaires des aides, le mandataire doit respecter des engagements et présenter des garanties. Les engagements portent notamment sur la restitution des aides indûment perçues pour le compte du mandant, sur les déclarations préalables à l'Agence nationale de l'habitat et sur les conditions d'exercice de l'activité. Les garanties concernent notamment les aspects financiers, la compétence, la probité et les moyens appropriés. Un mandataire qui ne respecte pas les engagements et garanties requis ne peut être désigné en cette qualité auprès de l'agence pour le compte d'un bénéficiaire des aides. Un décret précise ces engagements et garanties ainsi que leur périmètre.</p>
<p>II. - L'Agence nationale de l'habitat peut sanctionner les bénéficiaires des aides, leurs mandataires et les signataires d'une convention prévue aux articles L. 321-4 ou L. 321-8 qui ont contrevenu aux règles ou aux conventions conclues. Elle peut refuser toute nouvelle demande d'aide provenant d'un même bénéficiaire ou d'un mandataire, personne physique ou morale, pendant une durée maximale de cinq ans. Lorsque le mandataire est une personne morale, cette sanction peut aussi viser les présidents et les dirigeants en fonction au moment du manquement. Sa durée ne peut alors dépasser celle de la sanction prononcée contre la personne morale concernée.</p>
<p>III. - L'agence peut également infliger des sanctions pécuniaires en fonction de la gravité des faits reprochés et de la situation financière de la personne physique ou morale concernée. Pour une personne physique, la sanction est plafonnée à la moitié de l'aide accordée ou à une somme équivalente à deux ans de loyer. Pour une personne morale, elle est plafonnée à dix fois le montant de l'aide accordée par dossier ou, si cette valeur est inférieure et déterminable, à 4 % du dernier chiffre d'affaires hors taxes connu à la date des faits. Ce dernier taux est porté à 6 % en cas de manquements réitérés.</p>
<p>Selon la gravité des faits reprochés, la décision qui inflige une sanction pécuniaire à une personne physique ou morale est rendue publique, en tout ou partie, sur le site internet de l'agence. Avant sa publication, elle doit être traitée de façon à rendre impossible l'identification des tiers. La publication ne peut intervenir qu'après l'expiration des délais de recours administratifs et contentieux, et sa durée ne peut dépasser cinq ans. Un décret en Conseil d'Etat précise les modalités d'application du présent alinéa.</p>
<p>IV. - Avant de prononcer les sanctions prévues aux II et III, l'agence met les personnes concernées en mesure de présenter leurs observations.</p>
""", "Réécriture à droit constant : les engagements et garanties des mandataires, les sanctions d'exclusion, les plafonds pécuniaires et les conditions de publicité sont séparés en phrases avec des sujets explicites. Le contradictoire reste au IV. Aucun montant, motif ou pouvoir de sanction n'est ajouté.",
"I à IV et alinéa distinct sur la publicité maintenus. Contrôle des cinq ans d'exclusion, de la limite applicable aux dirigeants en fonction au moment des faits, de la moitié de l'aide ou des deux ans de loyer, du plafond par dossier de dix fois l'aide, du plafond alternatif inférieur et déterminable de 4 % du chiffre d'affaires hors taxes connu à la date des faits et du taux de 6 % en cas de réitération. Le « ou » de la source pour les plafonds des personnes physiques est conservé, sans lui substituer une règle de cumul ou de minimum. Publicité selon la gravité, protection des tiers, expiration des deux catégories de délais de recours, plafond de publication de cinq ans et observations préalables conservés.")

add('L321-3', """
<p>Pour bénéficier de l'aide de l'Agence nationale de l'habitat destinée aux travaux d'amélioration d'un logement à usage locatif, le propriétaire doit donner ce logement en location pendant la durée fixée par le règlement général de l'agence.</p>
""", "Réécriture à droit constant : la condition de mise en location est formulée comme une obligation explicite du propriétaire bénéficiaire de l'aide. La durée reste fixée par le règlement général de l'agence ; aucune nouvelle durée ni réforme de fond n'est introduite.",
"Le champ reste celui de l'aide au propriétaire d'un logement locatif pour des travaux d'amélioration. La durée d'engagement locatif ne doit pas être confondue avec la période de vingt-quatre mois envisagée pour une rénovation locative : cette dernière exige notamment des dispositions dans les articles 6 et 20-1 de la loi n° 89-462 du 6 juillet 1989 et ses textes de décence. Les règles d'impayés nécessitent une coordination distincte de l'article 24 de cette loi et des dispositions procédurales applicables ; elles ne sont pas modifiées par une condition d'aide de l'Anah.")


def main():
    sources = json.loads(Path('source.json').read_text())
    assert len(sources) == 24
    assert set(drafts) == {a['number'] for a in sources}
    answer = []
    for source in sources:
        row = {key: source[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}
        row.update(drafts[source['number']])
        answer.append(row)
    Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')


if __name__ == '__main__':
    main()
